DEFAULT_SHIFTS = [("Noche", time(22), time(6), "#5b5bd6"), ("Mañana", time(6), time(14), "#2f80ed"),
                  ("Tarde", time(14), time(22), "#16a39a")]


def create_default_shifts(apps, schema_editor):
    """Crea Noche/Mañana/Tarde por planta y asigna a cada línea los turnos que caben en su jornada anterior."""
    Site = apps.get_model("mes_core", "Site")
    Shift = apps.get_model("mes_core", "Shift")
    WorkCenter = apps.get_model("mes_core", "WorkCenter")
    for site in Site.objects.all():
        created = [Shift.objects.create(site=site, name=n, start_time=a, end_time=b, color=c)
                   for n, a, b, c in DEFAULT_SHIFTS]
        for wc in WorkCenter.objects.filter(site=site):
            if wc.shift_start == wc.shift_end:
                continue  # era 24 h: sin turnos propios = todos los de la planta
            fits = [s for s in created if s.start_time < s.end_time
                    and s.start_time >= wc.shift_start and s.end_time <= wc.shift_end]
            wc.shifts.set(fits or created)


